id2433FunctionSources.quizMeaningOptions:
function quizMeaningOptions(it,def,example='') {
  const entry=REVIEWED_MEANING_QUIZZES[it.kind+'_'+it.id];
  const cardExamples=(it.kind==='g'?GRAMMAR_DETAILS_BY_ID:VOCAB_DETAILS_BY_ID)[it.id]?.examples || [];
  const reviewed=reviewedExampleTarget(example,it.kind,it.word.w)?.quiz || entry?.byExample?.[example] ||
    ((!example || cardExamples.includes(example)) ? entry : null);
  if(reviewed)return {correct:reviewed.correct,wrong:reviewed.wrong.slice(),note:reviewed.note};
  const correct=quizDefinitionText(it.kind,it.id,def.m);
  const rows=quizCandidateRows(it,def),seen=new Set([correct]),ranked=[];
  for(const row of rows)if(!seen.has(row.choice)){seen.add(row.choice);ranked.push(row);}
  // Randomize only among candidates with close scores, keeping the best relevant group.
  const top=ranked.length?ranked[0].score:0;
  const shortlist=ranked.filter(r=>r.score>=top-2).slice(0,8);
  const chosen=shuffleArray(shortlist).slice(0,3);
  for(const row of ranked)if(chosen.length<3&&!chosen.includes(row))chosen.push(row);
  return {correct,wrong:chosen.map(r=>r.choice),note:''};
}

id2433FunctionSources.clozeWordCandidates:
function clozeWordCandidates(item) {
  if(item.kind!=='v')return [];
  const pos=vocabPartOfSpeech(item.id).join('|');
  return [...new Set(ACTIVE_VOCAB.filter(v=>v.id!==item.word.id&&VOCAB_DETAILS_BY_ID[v.id]&&vocabPartOfSpeech(v.id).join('|')===pos&&!/[〜～・／/]/.test(v.w)).map(v=>v.w))];
}

id2433FunctionSources.markTarget:
markTarget(sentence, kind, word) {
    const exact = reviewedExampleTarget(sentence, kind, word);
    if (exact) {
      let result='', cursor=0;
      for (const form of exact.forms) {
        const idx=sentence.indexOf(form,cursor);
        if (idx < 0) return {s:sentence,found:false};
        result+=sentence.slice(cursor,idx)+'\u0001'+form+'\u0002';
        cursor=idx+form.length;
      }
      return {s:result+sentence.slice(cursor),found:true};
    }

    // Bind each reviewed inflection to its complete source example. A changed
    // sentence must be reviewed again; never match a short stem in arbitrary text.
    const reviewed = kind === 'v' && VOCAB_KANA_EXAMPLE_TARGETS[word];
    const form = reviewed && Object.prototype.hasOwnProperty.call(reviewed, sentence) ? reviewed[sentence] : null;
    if (form) {
      const idx = sentence.indexOf(form);
      if (idx >= 0) return { s: sentence.slice(0, idx) + '\u0001' + form + '\u0002' + sentence.slice(idx + form.length), found: true };
    }
    let pieces;
    if (kind === 'g') pieces = word.replace(/^[〜～]/, '').split(/[〜～…・／\/（）()]/).map(s => s.trim()).filter(Boolean);
    else pieces = word.replace(/^[〜～]/, '').split('・').filter(Boolean);
    let s = sentence, found = false;
    for (const piece of pieces) {
      let cand = piece, idx = s.indexOf(cand);
      while (idx < 0 && /[一-鿿]/.test(cand) && cand.length > 2 && /[぀-ゟ]$/.test(cand)) { cand = cand.slice(0, -1); idx = s.indexOf(cand); }
      if (idx < 0 && cand.length === 2 && /[぀-ゟ]$/.test(cand) && /[一-鿿]/.test(cand[0])) { cand = cand[0]; idx = s.indexOf(cand); }
      if (idx >= 0) { s = s.slice(0, idx) + '\u0001' + cand + '\u0002' + s.slice(idx + cand.length); found = true; }
    }
    return { s, found };
  }

id2433FunctionSources.getDefinition:
getDefinition(word, kind = 'v', id = null) {
    if (kind === 'v') word=canonicalVocabLabel(word);
    const cleanWord = word.replace(/^[〜～]/, '');

    // 文法項目（kind === 'g'）
    if (kind === 'g') {
      if (id && GRAMMAR_DETAILS_BY_ID[id]) {
        return GRAMMAR_DETAILS_BY_ID[id];
      }
      const matchedGrammar = GRAMMAR.find(g => {
        if (id && String(g.id) === String(id)) return true;
        const gw = (g.w || '').replace(/^[〜～]/, '');
        return g.w === word || gw === cleanWord;
      });
      if (matchedGrammar && GRAMMAR_DETAILS_BY_ID[matchedGrammar.id]) {
        return GRAMMAR_DETAILS_BY_ID[matchedGrammar.id];
      }
      const gItem = matchedGrammar || { c: '文法表現', g: '重要', w: word };
      return {
        m: `N1文法「${word}」（分類：${gItem.c}・p.${gItem.g}）。主に論説文・評論文・公式文書で用いられる重要文法。`,
        t: `японський граматичний зворот (${cleanWord})`,
        s: ['文法機能語'],
        examples: [
          `本件の重大な影響を鑑みれば、いかなる反対があろうとも<b>${word}</b>、責任ある決断を下さねばならない。`,
          `長年にわたる詳細な現地調査の結果を踏まえた上で、<b>${word}</b>慎重な対応が強く求められている。`
        ]
      };
    }

    // 語彙項目（kind === 'v'）
    if (id && VOCAB_DETAILS_BY_ID[id] && VOCAB_DETAILS_BY_ID[id].w === word) {
      const d = VOCAB_DETAILS_BY_ID[id];
      return { m: d.m, t: d.t, s: d.s, examples: d.examples, usage: d.usage };
    }

    if (SPECIAL_VOCAB_DICT[word]) {
      const b = SPECIAL_VOCAB_DICT[word];
      return {
        m: b.m,
        t: b.t,
        s: ['重要語彙'],
        examples: [
          `市場環境が激変する中で、今回の戦略において「${word}」が果たす役割は極めて大きい。`,
          `組織改革を迅速に推進するためには、「${word}」に対する共通の理解を深めることが不可欠だ。`
        ]
      };
    }

    const vocabItem = ACTIVE_VOCAB.find(v => (id && String(v.id) === String(id)) || v.w === word);
    const cat = vocabItem ? (vocabItem.c || '') : '';

    // カタカナ語の自動判定
    const isKatakana = /^[\u30A0-\u30FF\u30FC]+$/.test(word);
    if (isKatakana || cat.includes('カタカナ')) {
      return {
        m: `外来語・国際文脈において広く定着している重要カタカナ語。`,
        t: `${word.toLowerCase()}`,
        s: ['外来語', 'カタカナ表現'],
        examples: [
          `グローバルな市場競争の中で、組織の「${word}」を最大限に引き出す戦略が求められている。`,
          `既存の枠組みにとらわれず、新たな「${word}」を取り入れることで業務の効率化を図る。`
        ]
      };
    }

    let meaningDesc = `論説・評論文・ビジネスなどの公的文脈において高頻度で用いられるN1重要語。`;
    let transDesc = `${word}`;
    let ex1 = `激変する国際情勢の中で、本件における「${word}」を巡る慎重な対応が求められている。`;
    let ex2 = `従来の固定観念にとらわれることなく、「${word}」の長期的影響を見極めるべきだ。`;

    if (cat.includes('動詞')) {
      meaningDesc = `動作や作用、状態の変化を表す動詞表現。`;
      transDesc = `to ${word}`;
      ex1 = `いかなる困難が立ちはだかろうとも、最後まで責任を${word}覚悟が必要だ。`;
      ex2 = `複雑に絡み合う利害関係を${word}ことこそが、組織全体の信頼回復につながる。`;
    } else if (cat.includes('形容詞')) {
      meaningDesc = `事物の状態や人の感情・性質を修飾する表現。`;
      transDesc = `${word} (adjective)`;
      ex1 = `表面的な数値のみに安住せず、現場を取り巻く${word}現状を直視しなければならない。`;
      ex2 = `長年の弛まぬ研鑽と組織改革の成果が、ここにきて${word}変化として現れ始めている。`;
    } else if (cat.includes('副詞') || cat.includes('オノマトペ')) {
      meaningDesc = `状態や程度、心理的なニュアンスを生き生きと修飾する表現。`;
      transDesc = `${word} (adverb)`;
      ex1 = `周囲の反対意見を${word}押し切ってまで、新規事業への投資に踏み切った。`;
      ex2 = `予断を許さない緊迫した状況の中、状況の変化を${word}注視し続けた。`;
    }

    return {
      m: meaningDesc,
      t: transDesc,
      s: ['関連語彙'],
      examples: [ex1, ex2]
    };
  }
